// Prepare daily operations audit prompt for the Central Orchestrator
return [{
  json: {
    message: "Perform daily operations audit: assess room occupancy, verify rent collections, inspect maintenance tasks, and check safety approval gates.",
    caller_role: "admin",
    email: "admin@stayops.com",
    source: "scheduled_heartbeat"
  }
}];

// Parse & normalize incoming webhook request
const body = $json.body || $json;

const prompt = String(body.message || body.prompt || body.text || "status").trim();
const caller_role = String(body.caller_role || body.role || body.user_role || "property_manager").toLowerCase().trim();
const email = body.email || (caller_role === "tenant" ? "resident@stayops.com" : "admin@stayops.com");
const tenant_id = body.tenant_id || "T-001";
const notice_days = body.notice_days || 15;

return [{
  json: {
    message: prompt,
    caller_role: caller_role,
    email: email,
    tenant_id: tenant_id,
    notice_days: notice_days,
    source: body.source || "webhook",
    received_at: new Date().toISOString()
  }
}];

// Agent 6: Orchestrator Agent (Central Workflow Coordinator)
// Analyzes request, determines required specialized agents, tracks workflow state, and chooses execution path.
const input = ;
const msg = (input.message || '').toLowerCase();

let scenario = 'direct_inquiry';
let required_agents = [];

if (msg.includes('move out') || msg.includes('vacat') || msg.includes('leaving') || msg.includes('15 day')) {
  scenario = 'move_out_workflow';
  required_agents = [
    'Tenant Support Agent',
    'Vacancy and Revenue Recovery Agent',
    'Lead and Leasing Agent',
    'Rent and Collections Agent',
    'Maintenance and Vendor Agent',
    'Monitoring and Facilitator Agent'
  ];
} else if (msg.includes('lead') || msg.includes('enquiry') || msg.includes('book') || msg.includes('visit') || msg.includes('room') || msg.includes('bed') || msg.includes('allocate') || msg.includes('viman') || msg.includes('flat') || msg.includes('budget')) {
  scenario = 'direct_leasing';
  required_agents = ['Lead and Leasing Agent', 'Monitoring and Facilitator Agent'];
} else if (msg.includes('approval') || msg.includes('safety') || msg.includes('gate') || msg.includes('support') || msg.includes('rule') || msg.includes('wifi') || msg.includes('key') || msg.includes('ticket')) {
  scenario = 'direct_tenant_support';
  required_agents = ['Tenant Support Agent', 'Monitoring and Facilitator Agent'];
} else if (msg.includes('maintain') || msg.includes('repair') || msg.includes('plumb') || msg.includes('leak') || msg.includes('electric') || msg.includes('vendor')) {
  scenario = 'direct_maintenance';
  required_agents = ['Maintenance and Vendor Agent', 'Monitoring and Facilitator Agent'];
} else if (msg.includes('rent') || msg.includes('due') || msg.includes('payment') || msg.includes('overdue') || msg.includes('collect')) {
  scenario = 'direct_collections';
  required_agents = ['Rent and Collections Agent', 'Monitoring and Facilitator Agent'];
} else if (msg.includes('occupancy') || msg.includes('vacan') || msg.includes('revenue') || msg.includes('downtime') || msg.includes('loss')) {
  scenario = 'direct_vacancy';
  required_agents = ['Vacancy and Revenue Recovery Agent', 'Monitoring and Facilitator Agent'];
} else {
  scenario = 'direct_inquiry';
  required_agents = ['Central Orchestrator Agent', 'Monitoring and Facilitator Agent'];
}

return [{
  json: {
    ...input,
    orchestrator_decision: {
      scenario: scenario,
      coordination_mode: scenario === 'move_out_workflow' ? 'parallel_branching' : 'direct_dispatch',
      required_agents: required_agents,
      coordinated_by: 'Central Orchestrator Agent',
      timestamp: new Date().toISOString()
    }
  }
}];

// Agent 2: Tenant Support Agent (Move-Out Notice Ingestion)
// Manages resident communication, validates notice duration, records departure schedule.
const input = $json;
const noticeDays = input.notice_days || 15;
const targetDate = new Date();
targetDate.setDate(targetDate.getDate() + noticeDays);

const tenantOutput = {
  agent: "Tenant Support Agent",
  status: "notice_recorded",
  tenant_id: input.tenant_id,
  notice_days: noticeDays,
  expected_move_out_date: targetDate.toISOString().split("T")[0],
  room_number: "204",
  bed_number: "204-A",
  property_name: "StayOps Prime Residency - Koramangala",
  departure_reason: "Relocating for work / academic semester end",
  resident_history_logged: true,
  action_summary: `Tenant ${input.tenant_id} 15-day departure registered for room 204. Orchestrating parallel vacancy recovery and rent audits.`
};

return [{
  json: {
    ...input,
    tenant_support_result: tenantOutput
  }
}];

// Agent 5: Vacancy and Revenue Recovery Agent (Move-Out Parallel Branch A)
// Analyzes vacancy downtime loss, searches pipeline customer enquiries for matching preferences.
const input = $json;
const rentMonthly = 14500;
const downtimeLossDaily = (rentMonthly / 30).toFixed(2);

const matchingLeads = [
  {
    lead_id: "L-102",
    name: "Vikram Rathore",
    preferred_location: "Koramangala, Bengaluru",
    budget: 15000,
    room_type: "Double Sharing",
    move_in_urgency: "Immediate / Next 15 days",
    match_score: "94%"
  },
  {
    lead_id: "L-108",
    name: "Ananya Iyer",
    preferred_location: "Koramangala",
    budget: 14000,
    room_type: "Double Sharing",
    move_in_urgency: "Within 2 weeks",
    match_score: "91%"
  }
];

const vacancyOutput = {
  agent: "Vacancy and Revenue Recovery Agent",
  status: "pipeline_matched",
  vacating_room: "Room 204 (Bed 204-A)",
  rent_rate: rentMonthly,
  potential_30day_loss: `₹${rentMonthly}`,
  mitigation_strategy: "Early prospective lead engagement prior to tenant vacate date",
  matched_pipeline_leads: matchingLeads,
  action_summary: `Identified 2 matching pipeline enquiries to backfill Room 204. Handing over to Lead & Leasing Agent for instant tour scheduling.`
};

return [{
  json: {
    ...input,
    vacancy_recovery_result: vacancyOutput
  }
}];

// Agent 1: Lead and Leasing Agent (Move-Out Follow-Up)
// Receives matched leads from Vacancy Agent, prepares outreach, schedules property visits.
const input = $json;
const matchedLeads = input.vacancy_recovery_result?.matched_pipeline_leads || [];

const outreachActions = matchedLeads.map((lead, idx) => ({
  lead_id: lead.lead_id,
  candidate_name: lead.name,
  action: "WhatsApp & Email Invitation Dispatched",
  proposed_visit: new Date(Date.now() + (idx + 1) * 86400000).toISOString().split("T")[0] + " 15:00 IST",
  room_offered: "Room 204 (StayOps Prime)",
  status: "tour_invite_sent"
}));

const leasingOutput = {
  agent: "Lead and Leasing Agent",
  status: "outreach_initiated",
  scheduled_visits_count: outreachActions.length,
  outreach_log: outreachActions,
  action_summary: `Contacted ${outreachActions.length} qualified leads with personalized room walk-through schedules to eliminate vacancy gap.`
};

return [{
  json: {
    ...input,
    leasing_result: leasingOutput
  }
}];

// Agent 4: Rent and Collections Agent (Move-Out Parallel Branch B)
// Runs simultaneously with Vacancy & Leasing. Audits rent ledger, pending dues, security deposit.
const input = $json;
const depositHeld = 28000;
const pendingRent = 0; // Tenant is in good standing
const utilityDues = 850;
const refundEstimated = depositHeld - (pendingRent + utilityDues);

const collectionsOutput = {
  agent: "Rent and Collections Agent",
  status: "ledger_audited",
  tenant_id: input.tenant_id,
  rent_status: "Paid (Up to date)",
  pending_rent_amount: `₹${pendingRent}`,
  utility_dues_accrued: `₹${utilityDues}`,
  security_deposit_held: `₹${depositHeld}`,
  estimated_refundable_deposit: `₹${refundEstimated}`,
  financial_clearance: "Approved (Subject to final checkout turnover inspection)",
  action_summary: `Ledger audited. Tenant in good financial standing. Outstanding utilities of ₹850 earmarked from security deposit.`
};

return [{
  json: {
    ...input,
    collections_result: collectionsOutput
  }
}];

// Agent 3: Maintenance and Vendor Agent (Move-Out Turnover Inspection)
// Receives parallel inputs from both branches. Plans room turnover inspection, schedules vendor, checks cost approval gate.
const input = $json;

const estimatedCost = 3500;
const approvalThreshold = 5000;
const requiresApproval = estimatedCost > approvalThreshold;

const maintenanceOutput = {
  agent: "Maintenance and Vendor Agent",
  status: "turnover_scheduled",
  room_number: "204",
  tasks: [
    "Full sanitization & deep cleaning",
    "Wall touchup painting",
    "AC filter cleaning & electrical inspection"
  ],
  assigned_vendor: "Apex Facility Services (Cleaners & Electricians)",
  scheduled_inspection_date: input.tenant_support_result?.expected_move_out_date || new Date().toISOString().split("T")[0],
  estimated_service_cost: `₹${estimatedCost}`,
  requires_manager_approval: requiresApproval,
  approval_status: requiresApproval ? "Pending Property Manager Approval" : "Auto-Approved (Under ₹5,000 Safety Threshold)",
  action_summary: `Turnover inspection scheduled for Room 204 with Apex Facility Services. Service estimate ₹${estimatedCost} auto-approved.`
};

return [{
  json: {
    ...input,
    maintenance_result: maintenanceOutput
  }
}];

// Agent 7: Monitoring and Facilitator Agent (Move-Out Supervisory Quality Gate)
// Supervises the multi-agent workflow. Checks task completeness, cross-verifies financial vs room status,
// detects conflicting information, replans or certifies completion.
const input = $json;

const checks = [];
let hasConflict = false;
let conflictDescription = "";

// 1. Verify Tenant Support Output
if (input.tenant_support_result?.expected_move_out_date) {
  checks.push({ agent: "Tenant Support Agent", check: "Notice & Departure Date Verified", passed: true });
} else {
  hasConflict = true;
  conflictDescription = "Tenant move-out date missing.";
}

// 2. Verify Vacancy & Leasing Synergy
const leadsCount = input.leasing_result?.scheduled_visits_count || 0;
if (leadsCount > 0) {
  checks.push({ agent: "Vacancy & Leasing Agents", check: "Pipeline lead backfill active", passed: true, details: `${leadsCount} tours scheduled` });
} else {
  checks.push({ agent: "Vacancy & Leasing Agents", check: "Lead pipeline warning", passed: true, details: "No matching leads found; public listing requested" });
}

// 3. Verify Rent Clearance
if (input.collections_result?.financial_clearance) {
  checks.push({ agent: "Rent and Collections Agent", check: "Ledger and security deposit audited", passed: true });
} else {
  hasConflict = true;
  conflictDescription = "Rent ledger not reconciled.";
}

// 4. Verify Turnover Maintenance
if (input.maintenance_result?.assigned_vendor) {
  checks.push({ agent: "Maintenance and Vendor Agent", check: "Turnover vendor assigned & safety gate cleared", passed: true });
}

const facilitatorOutput = {
  agent: "Monitoring and Facilitator Agent",
  status: hasConflict ? "conflict_detected_replanning" : "workflow_certified",
  supervision_audit: checks,
  all_tasks_completed: !hasConflict,
  integrity_score: hasConflict ? "60%" : "100%",
  conflicts_detected: hasConflict ? conflictDescription : "None. All multi-agent dependencies reconciled.",
  certified_at: new Date().toISOString(),
  action_summary: "Multi-agent coordination supervised and certified. Zero data conflicts detected between Leasing, Collections, and Maintenance."
};

return [{
  json: {
    ...input,
    facilitator_supervision: facilitatorOutput
  }
}];

// Agent 1: Lead and Leasing Agent (Direct Enquiries)
const input = $json;
return [{
  json: {
    ...input,
    specialized_agent_result: {
      agent: "Lead and Leasing Agent",
      status: "enquiry_processed",
      recommended_options: [
        { room: "101-B", property: "StayOps Koramangala", price: "₹12,500/mo", type: "Twin Sharing", amenities: "WiFi, Food, Laundry" },
        { room: "204-A", property: "StayOps Prime", price: "₹14,500/mo", type: "Double Sharing", amenities: "Attached Balcony, Gym, AC" }
      ],
      lead_profile: { qualified: true, budget_match: "Optimal", next_step: "Schedule Visit / Book Room" },
      action_summary: "Identified 2 available rooms matching your criteria and generated instant visit slots."
    }
  }
}];

// Agent 2: Tenant Support Agent (Direct Support)
const input = $json;
return [{
  json: {
    ...input,
    specialized_agent_result: {
      agent: "Tenant Support Agent",
      status: "ticket_created_and_answered",
      ticket_id: "TICK-902",
      priority: "Normal",
      topic: "Resident Support & Facilities",
      response_message: "Your query regarding property services has been logged. Support team has confirmed resolution within 4 hours.",
      action_summary: "Resident inquiry logged into support queue with normal priority."
    }
  }
}];

// Agent 3: Maintenance and Vendor Agent (Direct Maintenance)
const input = $json;
return [{
  json: {
    ...input,
    specialized_agent_result: {
      agent: "Maintenance and Vendor Agent",
      status: "vendor_assigned",
      ticket_id: "MAINT-410",
      category: "Plumbing / Electrical Repairs",
      assigned_vendor: "QuickFix Solutions (Rajesh Kumar)",
      estimated_cost: "₹1,200",
      approval_needed: false,
      scheduled_time: "Today between 14:00 - 16:00 IST",
      action_summary: "Vendor assigned for maintenance request. Inspection scheduled with zero disruption."
    }
  }
}];

// Agent 4: Rent and Collections Agent (Direct Collections)
const input = $json;
return [{
  json: {
    ...input,
    specialized_agent_result: {
      agent: "Rent and Collections Agent",
      status: "collections_summary_generated",
      metrics: {
        total_rent_expected: "₹4,25,000",
        total_collected: "₹3,90,000",
        collection_rate: "91.8%",
        pending_tenants_count: 3,
        automated_reminders_sent: 3
      },
      action_summary: "Portfolio financial status updated. Rent collection rate at 91.8% with reminders dispatched."
    }
  }
}];

// Agent 5: Vacancy and Revenue Recovery Agent (Direct Analytics)
const input = $json;
return [{
  json: {
    ...input,
    specialized_agent_result: {
      agent: "Vacancy and Revenue Recovery Agent",
      status: "occupancy_report_generated",
      metrics: {
        current_occupancy: "87.5%",
        vacant_beds: 4,
        total_beds: 32,
        projected_monthly_downtime_loss: "₹48,000",
        pricing_recommendation: "Dynamic 5% early-bird discount on remaining 2 Twin beds to hit 95% occupancy within 7 days."
      },
      action_summary: "Occupancy analyzed at 87.5%. Dynamic pricing recommendations submitted to property manager."
    }
  }
}];

// Agent 7: Monitoring and Facilitator Agent (General Quality Gate)
const input = $json;
const specResult = input.specialized_agent_result || {};

return [{
  json: {
    ...input,
    facilitator_supervision: {
      agent: "Monitoring and Facilitator Agent",
      status: "workflow_certified",
      all_tasks_completed: true,
      integrity_score: "100%",
      inspected_agent: specResult.agent || "Specialized Agent",
      conflicts_detected: "None",
      certified_at: new Date().toISOString(),
      action_summary: `Supervised execution of ${specResult.agent || "Agent"}. Validated payload consistency and security bounds.`
    }
  }
}];

// Consolidate & synthesize multi-agent operations report
const apiResp = ($json && $json.body) ? $json.body : ($json || {});

let baseData = {};
try {
  baseData = $('Agent 7: Monitoring & Facilitator Agent (Move-Out)').first()?.json ||
             $('Agent 7: Monitoring & Facilitator Agent (General)').first()?.json || {};
} catch (e) {
  baseData = {};
}

let orchDecision = baseData.orchestrator_decision;
if (!orchDecision) {
  try { orchDecision = $('Agent 6: Orchestrator Agent').first()?.json?.orchestrator_decision || {}; } catch(e) { orchDecision = {}; }
}

let tenantSupport = baseData.tenant_support_result;
if (!tenantSupport) {
  try { tenantSupport = $('Agent 2: Tenant Support Agent (Move-Out)').first()?.json?.tenant_support_result; } catch(e) {}
}

let vacancyRecovery = baseData.vacancy_recovery_result;
if (!vacancyRecovery) {
  try { vacancyRecovery = $('Agent 5: Vacancy & Revenue Recovery Agent (Move-Out)').first()?.json?.vacancy_recovery_result; } catch(e) {}
}

let leasingRes = baseData.leasing_result;
if (!leasingRes) {
  try { leasingRes = $('Agent 1: Lead and Leasing Agent (Move-Out)').first()?.json?.leasing_result; } catch(e) {}
}

let collectionsRes = baseData.collections_result;
if (!collectionsRes) {
  try { collectionsRes = $('Agent 4: Rent and Collections Agent (Move-Out)').first()?.json?.collections_result; } catch(e) {}
}

let maintenanceRes = baseData.maintenance_result;
if (!maintenanceRes) {
  try { maintenanceRes = $('Agent 3: Maintenance and Vendor Agent (Move-Out)').first()?.json?.maintenance_result; } catch(e) {}
}

let facilitatorAudit = baseData.facilitator_supervision;
let specResult = baseData.specialized_agent_result;

const isMoveOut = orchDecision.scenario === "move_out_workflow";

let synthesizedMessage = "";
if (isMoveOut) {
  synthesizedMessage = `[StayOps Multi-Agent Operations] 15-Day Move-Out Workflow Successfully Executed.\n` +
    `• Tenant Support Agent: Departure registered for Room 204 (Target Date: ${tenantSupport?.expected_move_out_date || "in 15 days"}).\n` +
    `• Vacancy & Revenue Agent: Identified 2 pipeline customer matches to mitigate downtime revenue loss.\n` +
    `• Lead & Leasing Agent: Prepared personalized tours for ${leasingRes?.scheduled_visits_count || 2} qualified leads.\n` +
    `• Rent & Collections Agent: Rent up-to-date; ₹850 accrued utilities deducted from security deposit.\n` +
    `• Maintenance & Vendor Agent: Turnover inspection scheduled with Apex Facility Services.\n` +
    `• Facilitator Agent: Workflow certified with 100% integrity score. Zero operational conflicts.`;
} else if (apiResp.response) {
  synthesizedMessage = apiResp.response;
} else if (specResult?.action_summary) {
  synthesizedMessage = `[${specResult.agent}] ${specResult.action_summary}`;
} else {
  synthesizedMessage = "StayOps multi-agent operations processed your request successfully.";
}

return [{
  json: {
    status: "success",
    http_status: 200,
    title: isMoveOut ? "[MULTI-AGENT] 15-Day Move-Out Rebalancing Complete" : "[OPERATIONS] StayOps AI Dispatch Complete",
    coordinator: "Central Orchestrator Agent",
    supervisor: "Monitoring and Facilitator Agent",
    scenario: orchDecision.scenario || "direct_inquiry",
    active_agents: orchDecision.required_agents || [],
    response: synthesizedMessage,
    workflow_state: {
      tenant_support: tenantSupport || null,
      vacancy_recovery: vacancyRecovery || null,
      lead_leasing: leasingRes || null,
      rent_collections: collectionsRes || null,
      maintenance_vendor: maintenanceRes || null,
      specialized_result: specResult || null,
      facilitator_audit: facilitatorAudit || null
    },
    live_backend_sync: apiResp.action_performed || "synchronized",
    timestamp: new Date().toISOString()
  }
}];
